// Purpose: Validate Bounded Source Request. Keep this deterministic and fail closed.
const request = $json;
const required = [
    'run_id',
    'source_code',
    'folder_id',
    'senders',
    'subjects',
    'window_start',
    'run_upper_bound',
    'onedrive_parent_id',
];
for (const field of required) {
    if (request[field] === undefined || request[field] === null || request[field] === '') {
        throw new Error(`Missing trusted contract field ${field}`);
    }
}
if (!Array.isArray(request.senders) || !request.senders.length) {
    throw new Error('Trusted sender allowlist is required');
}
if (!Array.isArray(request.subjects) || !request.subjects.length) {
    throw new Error('Trusted subject-fragment allowlist is required');
}
const windowStart = new Date(request.window_start);
const runUpperBound = new Date(request.run_upper_bound);
if (!(windowStart < runUpperBound) || runUpperBound > new Date()) {
    throw new Error('Acquisition window must be positive and frozen no later than now');
}
const senders = request.senders.map(value => String(value).trim().toLowerCase());
const subjects = request.subjects.map(value => String(value).trim()).filter(Boolean);
const maxMessages = Number(request.max_messages ?? 500);
if (!Number.isInteger(maxMessages) || maxMessages < 1 || maxMessages > 5000) {
    throw new Error('max_messages must be an integer from 1 through 5000');
}
const quoteOData = value => `'${String(value).replaceAll("'", "''")}'`;
const senderFilter = senders
    .map(sender => `from/emailAddress/address eq ${quoteOData(sender)}`)
    .join(' or ');
const subjectFilter = subjects
    .map(subject => `contains(subject,${quoteOData(subject)})`)
    .join(' or ');
return [{
        json: {
            ...request,
            senders,
            subjects,
            max_messages: maxMessages,
            window_end: runUpperBound.toISOString(),
            server_filter: `(${senderFilter}) and (${subjectFilter})`,
        },
    }];

// Purpose: Gate Microsoft Graph Circuit. Keep this deterministic and fail closed.
const now = new Date(), row = $json?.provider_code ? $json : { state: 'CLOSED', transient_failure_count: 0 }, retry = row.retry_after ? new Date(row.retry_after) : null;
if (row.state === 'OPEN' && retry && retry > now)
    throw new Error('PROVIDER_CIRCUIT_OPEN:MICROSOFT_GRAPH');
return [{ json: { provider_code: 'MICROSOFT_GRAPH', state: row.state === 'OPEN' ? 'HALF_OPEN' : 'CLOSED', transient_failure_count: Number(row.transient_failure_count || 0), last_error_class: row.last_error_class || '', opened_at: row.opened_at || null, retry_after: row.retry_after || null, readback_verified: false, updated_at: now.toISOString() } }];

// Purpose: Exact Sender Subject and Window Filter. Keep this deterministic and fail closed.
const contract = $('Validate Bounded Source Request').first().json;
const candidates = $('Get Messages from Configured Folder').all();
if (candidates.length > contract.max_messages) {
    throw new Error(`SOURCE_RESULT_LIMIT_EXCEEDED:${candidates.length}`);
}
const start = new Date(contract.window_start);
const end = new Date(contract.window_end);
return candidates
    .filter(item => {
    const message = item.json;
    const sender = String(message.from?.emailAddress?.address
        || message.sender?.emailAddress?.address
        || '').toLowerCase();
    const subject = String(message.subject || '').toLowerCase();
    const received = new Date(message.receivedDateTime);
    return contract.senders.includes(sender)
        && contract.subjects.some(fragment => subject.includes(fragment.toLowerCase()))
        && received >= start
        && received < end;
})
    .map(item => ({
    json: {
        ...item.json,
        source_code: contract.source_code,
        window_start: contract.window_start,
        window_end: contract.window_end,
        onedrive_parent_id: contract.onedrive_parent_id,
    },
}));

// Purpose: Preserve Every Attachment. Keep this deterministic and fail closed.
const message = $('Exact Sender Subject and Window Filter').item.json;
return $input.all().map(item => {
    const name = String(item.json.name || 'attachment.bin');
    const extension = name.includes('.') ? name.split('.').pop().toLowerCase() : 'bin';
    return {
        json: {
            ...item.json,
            message_id: message.id,
            source_code: message.source_code,
            onedrive_parent_id: message.onedrive_parent_id,
            extension,
            is_pdf: extension === 'pdf',
            is_inline: Boolean(item.json.isInline),
        },
    };
});

// Purpose: Enforce Native Upload Size. Keep this deterministic and fail closed.
const rawSize = String($binary?.data?.fileSize || '').trim().toLowerCase();
const match = rawSize.match(/^([0-9]+(?:\.[0-9]+)?)\s*(b|kb|mb)?$/);
let bytes = null;
if (match) {
    const scale = { b: 1, kb: 1024, mb: 1024 * 1024, '': 1 }[match[2] || ''];
    bytes = Math.ceil(Number(match[1]) * scale);
}
if (bytes !== null && bytes > 4 * 1024 * 1024) {
    throw new Error('LARGE_EVIDENCE_UPLOAD_SESSION_REQUIRED');
}
return [{ json: { ...$json, observed_binary_bytes: bytes }, binary: $binary }];

// Purpose: Verify Archived Original Readback. Keep this deterministic and fail closed.
const expected = String($('SHA-256 Original').item.json.document_sha256 || '').toLowerCase();
const observed = String($json.archive_readback_sha256 || '').toLowerCase();
if (!expected || observed !== expected) {
    throw new Error('ARCHIVE_ORIGINAL_READBACK_HASH_MISMATCH');
}
return [{ json: { ...$json, archive_readback_verified: true } }];

// Purpose: Build Original Email Evidence. Keep this deterministic and fail closed.
const message = $json;
const archivePayload = {
    schema_version: 1,
    message_id: message.id,
    internet_message_id: message.internetMessageId || null,
    received_at: message.receivedDateTime,
    sender: message.from?.emailAddress?.address || message.sender?.emailAddress?.address || null,
    subject: message.subject || '',
    body_type: message.body?.contentType || null,
    body: message.body?.content || '',
};
return [{
        json: {
            archive_payload: archivePayload,
            source_message_id: message.id,
            onedrive_parent_id: message.onedrive_parent_id,
        },
    }];

// Purpose: Verify Email Evidence Readback. Keep this deterministic and fail closed.
const expected = String($('SHA-256 Email Evidence').item.json.email_evidence_sha256 || '').toLowerCase();
const observed = String($json.email_readback_sha256 || '').toLowerCase();
if (!expected || observed !== expected) {
    throw new Error('EMAIL_EVIDENCE_READBACK_HASH_MISMATCH');
}
return [{ json: { email_evidence_sha256: observed, archive_readback_verified: true } }];

// Purpose: Shape Immutable Archive Input. Keep this deterministic and fail closed.
const request = $('Validate Bounded Source Request').first().json;
const rows = Array.isArray(request.messages) ? request.messages : [];
if (!rows.length) {
    return [{ json: { ...request, empty_inventory: true, attachment_inventory: [] } }];
}
const seen = new Set();
return rows.map(row => {
    const message = row?.message && typeof row.message === 'object' ? row.message : row;
    const messageId = String(row?.message_id || message?.id || '').trim();
    if (!messageId || seen.has(messageId)) throw new Error('IMMUTABLE_MESSAGE_ID_MISSING_OR_DUPLICATE');
    seen.add(messageId);
    return { json: { ...message, id: messageId, message_id: messageId, source_code: request.source_code, window_start: request.window_start, window_end: request.window_end, run_upper_bound: request.run_upper_bound, onedrive_parent_id: request.onedrive_parent_id, attachment_inventory: Array.isArray(row?.attachment_inventory) ? row.attachment_inventory : [] } };
});

// Purpose: Expand Enumerated Attachment Items. Keep this deterministic and fail closed.
const message = $json;
const attachments = Array.isArray(message.attachment_inventory) ? message.attachment_inventory : [];
return attachments.map(attachment => {
    const id = String(attachment?.id || '').trim();
    if (!id) throw new Error('IMMUTABLE_ATTACHMENT_ID_MISSING');
    const name = String(attachment.name || 'attachment.bin');
    const extension = name.includes('.') ? name.split('.').pop().toLowerCase() : 'bin';
    return { json: { ...attachment, id, attachment_id: id, source_attachment_id: id, message_id: message.message_id || message.id, source_message_id: message.message_id || message.id, source_code: message.source_code, onedrive_parent_id: message.onedrive_parent_id, extension, is_pdf: extension === 'pdf', is_inline: Boolean(attachment.isInline ?? attachment.is_inline) } };
});

// Purpose: Verify Enumerated Attachment Archive. Keep this deterministic and fail closed.
const expected = $('SHA-256 Enumerated Attachment').item.json;
const archived = $('Archive Enumerated Attachment in OneDrive').item.json;
const observed = String($json.archive_readback_sha256 || '').toLowerCase();
if (!expected.document_sha256 || observed !== String(expected.document_sha256).toLowerCase()) throw new Error('ARCHIVE_ATTACHMENT_READBACK_HASH_MISMATCH');
return [{ json: { ...expected, source_attachment_id: expected.source_attachment_id || expected.attachment_id || expected.id, source_message_id: expected.source_message_id || expected.message_id, onedrive_item_id: archived.id, onedrive_etag: archived.eTag || archived.etag || '', archive_state: 'HASH_VERIFIED', archive_readback_verified: true, attachment_verified: true, archive_readback_sha256: observed } }];

// Purpose: Verify Enumerated Archive Receipt. Keep this deterministic and fail closed.
const expected = $('Verify Enumerated Attachment Archive').item.json;
const receipt = $json;
if (receipt.archive_state !== 'HASH_VERIFIED' || receipt.source_message_id !== expected.source_message_id || receipt.source_attachment_id !== expected.source_attachment_id || receipt.source_sha256 !== expected.document_sha256) throw new Error('ARCHIVE_RECEIPT_READBACK_MISMATCH');
return [{ json: { ...expected, ...receipt, attachment_verified: true, replay_noop_key: `${receipt.source_message_id}:${receipt.source_attachment_id}:${receipt.source_sha256}` } }];

// Purpose: Attachment Verification Barrier. Keep this deterministic and fail closed.
const request = $('Validate Bounded Source Request').first().json;
const verified = $('Verify Enumerated Attachment Archive').all().map(item => item.json);
const legacy = $('Verify Archived Original Readback').all().map(item => item.json);
const observed = [...verified, ...legacy];
const expected = Array.isArray(request.messages) ? request.messages.flatMap(row => Array.isArray(row?.attachment_inventory) ? row.attachment_inventory : []) : observed;
const expectedIds = new Set(expected.map(item => String(item?.id || item?.attachment_id || '').trim()).filter(Boolean));
const observedIds = new Set(observed.map(item => String(item.source_attachment_id || item.attachment_id || item.id || '').trim()).filter(Boolean));
for (const id of expectedIds) if (!observedIds.has(id)) throw new Error(`ATTACHMENT_ARCHIVE_MISSING:${id}`);
if (observed.length !== expectedIds.size && expectedIds.size > 0) throw new Error('ATTACHMENT_ARCHIVE_COUNT_MISMATCH');
const first = observed[0] || {};
return [{ json: { status: 'ARCHIVED', run_id: request.run_id, source_code: request.source_code, onedrive_item_id: first.onedrive_item_id || null, source_message_id: first.source_message_id || null, source_attachment_id: first.source_attachment_id || null, attachment_verification_barrier: 'VERIFIED', attachment_ids_verified: true, attachments_verified: observed.length, archive_ready: true, cursor_commit_eligible: false } }];
